#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;

struct Matrix {
    int a[32][32];
    Matrix() { memset(a, 0, sizeof(a)); }
    Matrix operator*(const Matrix &b) const {
        Matrix c;
        for (int i = 0; i <= k; ++i)
            for (int j = 0; j <= k; ++j)
                for (int l = 0; l <= k; ++l)
                    c.a[i][l] = (c.a[i][l] + (long long)a[i][j] * b.a[j][l]) % MOD;
        return c;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n;
    int k;
    cin >> n >> k;

    vector<int> q;
    for (; n > 0; n /= k) q.push_back(n % k);
    reverse(q.begin(), q.end());

    vector<vector<Matrix>> f(q.size() + 1, vector<Matrix>(k + 1));
    Matrix identity;
    for (int i = 0; i <= k; ++i) {
        for (int j = 0; j <= k; ++j) {
            if (i == j || i == 0 || j == 0) identity.a[i][j] = 1;
        }
    }

    for (int i = 0; i < q.size(); ++i) {
        for (int j = 0; j < k; ++j) {
            f[i + 1][j] = identity;
            f[i + 1][j].a[j][j] = 1;
            f[i + 1][j].a[0][j] = 1;
        }
    }

    vector<Matrix> pre(q.size() + 1), suf(q.size() + 1);
    pre[0] = identity;
    suf[q.size()] = identity;

    for (int i = 1; i <= q.size(); ++i) {
        pre[i] = pre[i - 1] * f[i][0];
    }
    for (int i = q.size() - 1; i >= 0; --i) {
        suf[i] = f[i + 1][0] * suf[i + 1];
    }

    Matrix ans;
    ans.a[0][k] = 1;
    int sum = 0;
    for (int i = q.size() - 1; i >= 0; --i) {
        for (int j = 0; j < q[i]; ++j) {
            ans = ans * f[i + 1][(sum + j) % k];
        }
        sum = (sum + q[i]) % MOD;
    }

    int result = 0;
    for (int i = 0; i <= k; ++i) {
        result = (result + ans.a[0][i]) % MOD;
    }
    cout << result << "\n";
    return 0;
}
